using System;
using System.Collections.Generic;
using System.Diagnostics;
using System.IO;
using System.Linq;
using System.Threading;
using System.Windows;
using System.Windows.Media;
using System.Windows.Media.Imaging;
using System.Windows.Threading;
using MemeManager;
using MemeManager.Preprocessing;
using D=System.Drawing;

class PreprocessTests {
 static int count;static void Check(bool condition,string name){if(!condition)throw new Exception("FAIL: "+name);count++;Console.WriteLine("PASS: "+name);}
 static HashSet<int> FfmpegProcesses(){return new HashSet<int>(Process.GetProcessesByName("ffmpeg").Select(p=>{int id=p.Id;p.Dispose();return id;}));}
 [STAThread]static int Main(string[] args){try{if(args[0]=="lifecycle"){var timer=new DispatcherTimer{Interval=TimeSpan.FromMilliseconds(800)};timer.Tick+=(s,e)=>{timer.Stop();Application.Current.MainWindow.Close();};timer.Start();PreprocessProgram.Main(new[]{"--data-dir",args[1]});return 0;}Run(args[0],args[1]);Console.WriteLine(count+" preprocessing assertions passed.");return 0;}catch(Exception ex){Console.Error.WriteLine(ex);return 1;}}
 static void Run(string ffmpeg,string root){Directory.CreateDirectory(root);string source=Path.Combine(root,"输入 & 测试");Directory.CreateDirectory(source);string image=Path.Combine(source,"你好 &[x] 100%.png");
  using(var bitmap=new D.Bitmap(100,50,D.Imaging.PixelFormat.Format32bppArgb))using(var g=D.Graphics.FromImage(bitmap)){g.Clear(D.Color.FromArgb(128,255,0,0));bitmap.Save(image,D.Imaging.ImageFormat.Png);}
  byte[] original=File.ReadAllBytes(image);var options=new BatchOptions{FfmpegPath=ffmpeg,OutputDirectory=Path.Combine(root,"png"),Format="png",PreserveAnimation=false,Width=64,Height=64};
  string gif=Path.Combine(source,"动图.gif"),disguised=Path.Combine(source,"伪装.png"),broken=Path.Combine(source,"损坏.png");File.WriteAllBytes(gif,Convert.FromBase64String("R0lGODlhAQABAIAAAAAAAP///yH5BAAAAAAALAAAAAABAAEAAAIBRAA7"));File.Copy(gif,disguised);File.WriteAllText(broken,"broken");
  var batch=BatchProcessor.Run(new[]{image,gif,disguised,broken},options,CancellationToken.None,p=>{});Check(batch.Completed==1&&batch.Skipped==2&&batch.Failed==1,"mixed batch skips GIF signatures and reports bad files");Check(File.Exists(batch.ReportPath)&&File.ReadAllText(batch.ReportPath).Contains("失败"),"CSV records per-file failures");
  using(var output=(D.Bitmap)D.Bitmap.FromFile(batch.Entries[0].Output)){Check(output.Width==64&&output.Height==64,"contain produces exact dimensions");Check(output.GetPixel(32,0).A==0,"PNG letterboxing stays transparent");Check(output.GetPixel(32,32).A>=120&&output.GetPixel(32,32).A<=136,"PNG keeps source alpha");}
  Check(File.ReadAllBytes(image).SequenceEqual(original),"original input bytes remain unchanged");
  options.Format="gif";options.OutputDirectory=Path.Combine(root,"gif");var convertedGif=BatchProcessor.Run(new[]{image,gif,disguised},options,CancellationToken.None,p=>{});Check(convertedGif.Completed==1&&convertedGif.Skipped==2&&convertedGif.Entries[0].Output.EndsWith(".gif"),"non-GIF input converts to GIF while original GIF inputs are skipped");using(var stream=File.OpenRead(convertedGif.Entries[0].Output)){var decoder=new GifBitmapDecoder(stream,BitmapCreateOptions.None,BitmapCacheOption.OnLoad);Check(decoder.Frames.Count==1&&decoder.Frames[0].PixelWidth==64&&decoder.Frames[0].PixelHeight==64,"converted GIF is a valid single frame with unified dimensions");}
  string animationFolder=Path.Combine(root,"animation-input");Directory.CreateDirectory(animationFolder);D.Color[] frameColors={D.Color.Red,D.Color.Lime,D.Color.Blue};for(int i=0;i<3;i++)using(var frame=new D.Bitmap(16,12))using(var graphics=D.Graphics.FromImage(frame)){graphics.Clear(frameColors[i]);frame.Save(Path.Combine(animationFolder,"frame"+i+".png"),D.Imaging.ImageFormat.Png);}
  string pattern=Path.Combine(animationFolder,"frame%d.png"),apng=Path.Combine(animationFolder,"动画.apng"),webp=Path.Combine(animationFolder,"动画.webp");RunFfmpeg(ffmpeg,"-hide_banner -loglevel error -nostdin -n -framerate 5 -i "+BatchProcessor.Quote(pattern)+" -frames:v 3 -c:v apng -f apng -plays 0 "+BatchProcessor.Quote(apng));RunFfmpeg(ffmpeg,"-hide_banner -loglevel error -nostdin -n -framerate 5 -i "+BatchProcessor.Quote(pattern)+" -frames:v 3 -c:v libwebp_anim -lossless 1 -loop 0 "+BatchProcessor.Quote(webp));
  Check(BatchProcessor.IsAnimated(apng)&&BatchProcessor.IsAnimated(webp)&&!BatchProcessor.IsAnimated(image),"detects APNG and animated WebP without decoding their frames");options.PreserveAnimation=true;options.Format="gif";options.OutputDirectory=Path.Combine(root,"animation-gif");var animated=BatchProcessor.Run(new[]{apng,webp},options,CancellationToken.None,p=>{});Check(animated.Completed==2&&animated.Failed==0,"APNG and animated WebP convert to animated GIF");foreach(var entry in animated.Entries)using(var stream=File.OpenRead(entry.Output)){var decoder=new GifBitmapDecoder(stream,BitmapCreateOptions.None,BitmapCacheOption.OnLoad);Check(decoder.Frames.Count==3,"retains all three frames from "+Path.GetExtension(entry.Source));Check(decoder.Frames.All(f=>f.PixelWidth==64&&f.PixelHeight==64),"normalizes every animated frame");Check(decoder.Frames.Take(2).All(f=>Convert.ToInt32(((BitmapMetadata)f.Metadata).GetQuery("/grctlext/Delay"))==20),"preserves original 200 ms frame delays");for(int i=0;i<3;i++){var pixels=new FormatConvertedBitmap(decoder.Frames[i],PixelFormats.Bgra32,null,0);byte[] sample=new byte[4];pixels.CopyPixels(new Int32Rect(32,32,1,1),sample,4,0);Check(sample[2-i]>200,"preserves changing frame color "+i);}}
  string varying=Path.Combine(animationFolder,"不等帧时长.apng");RetimedApng(apng,varying);options.OutputDirectory=Path.Combine(root,"varying-gif");var varied=BatchProcessor.Run(new[]{varying},options,CancellationToken.None,p=>{});Check(varied.Completed==1,"converts variable-duration animation");using(var stream=File.OpenRead(varied.Entries[0].Output)){var decoder=new GifBitmapDecoder(stream,BitmapCreateOptions.None,BitmapCacheOption.OnLoad);int[] actual=decoder.Frames.Select(f=>Convert.ToInt32(((BitmapMetadata)f.Metadata).GetQuery("/grctlext/Delay"))).ToArray();Check(actual.SequenceEqual(new[]{12,24,36}),"preserves variable frame durations including final frame");}
  options.OutputDirectory=Path.Combine(root,"original-gif");string originalAnimated=animated.Entries[0].Output;var copied=BatchProcessor.Run(new[]{originalAnimated},options,CancellationToken.None,p=>{});Check(copied.Completed==1&&File.ReadAllBytes(copied.Entries[0].Output).SequenceEqual(File.ReadAllBytes(originalAnimated)),"existing animated GIF is preserved byte for byte and included among importable results");
  options.Format="jpg";options.OutputDirectory=Path.Combine(root,"animation-jpg");var protectedAnimation=BatchProcessor.Run(new[]{apng},options,CancellationToken.None,p=>{});Check(protectedAnimation.Skipped==1&&protectedAnimation.Completed==0,"static-only targets do not silently flatten animations");
  options.Format="keep";options.OutputDirectory=Path.Combine(root,"animation-keep");var kept=BatchProcessor.Run(new[]{apng,webp},options,CancellationToken.None,p=>{});Check(kept.Completed==2&&kept.Entries.All(x=>BatchProcessor.IsAnimated(x.Output)),"keep-format preserves APNG and WebP animation");options.PreserveAnimation=false;
  foreach(string format in new[]{"jpg","webp","bmp","keep"}){options.Format=format;options.OutputDirectory=Path.Combine(root,format);var result=BatchProcessor.Run(new[]{image},options,CancellationToken.None,p=>{});Check(result.Completed==1,"FFmpeg converts "+format);if(format=="jpg"||format=="bmp")using(var converted=(D.Bitmap)D.Bitmap.FromFile(result.Entries[0].Output)){var corner=converted.GetPixel(32,0);Check(corner.R>240&&corner.G>240&&corner.B>240,format+" composites transparency onto white");}}
  options.Format="png";foreach(string fit in new[]{"cover","stretch"}){options.Resize=fit;options.OutputDirectory=Path.Combine(root,fit);var result=BatchProcessor.Run(new[]{image},options,CancellationToken.None,p=>{});using(var bitmap=(D.Bitmap)D.Bitmap.FromFile(result.Entries[0].Output))Check(bitmap.Width==64&&bitmap.Height==64&&bitmap.GetPixel(0,0).A>120,fit+" fills requested dimensions without padding");}
  options.ResizeEnabled=false;options.Format="keep";options.OutputDirectory=source;var collision=BatchProcessor.Run(new[]{image},options,CancellationToken.None,p=>{});Check(collision.Completed==1&&collision.Entries[0].Output!=image&&File.ReadAllBytes(image).SequenceEqual(original),"same output directory never overwrites input");using(var bitmap=D.Image.FromFile(collision.Entries[0].Output))Check(bitmap.Width==100&&bitmap.Height==50,"format-only mode retains dimensions");
  string nested=Path.Combine(source,"nested");Directory.CreateDirectory(nested);File.Copy(image,Path.Combine(nested,"nested.png"));var shallow=BatchProcessor.Collect(new[]{source},false,CancellationToken.None);var recursive=BatchProcessor.Collect(new[]{source,source},true,CancellationToken.None);Check(recursive.Count==shallow.Count+1,"folder recursion is optional and paths deduplicate");
  var sources=new List<string>();string cancelFolder=Path.Combine(root,"cancel-input");Directory.CreateDirectory(cancelFolder);for(int i=0;i<40;i++){string file=Path.Combine(cancelFolder,i+".png");File.Copy(image,file);sources.Add(file);}options.OutputDirectory=Path.Combine(root,"cancel-output");var before=FfmpegProcesses();var watch=Stopwatch.StartNew();using(var token=new CancellationTokenSource(50)){var cancelled=BatchProcessor.Run(sources,options,token.Token,p=>{});Check(cancelled.Cancelled&&watch.Elapsed<TimeSpan.FromSeconds(5),"cancelling interrupts batch promptly");}Check(Directory.GetFiles(options.OutputDirectory,".shiqu-*").Length==0,"cancelled work removes temporary output");Check(!FfmpegProcesses().Except(before).Any(),"no FFmpeg worker survives cancellation");
  Check(!typeof(ManagerWindow).Assembly.GetReferencedAssemblies().Any(x=>x.Name=="MemePreprocessor"),"main application has no processing module dependency");
  using(var child=Process.Start(new ProcessStartInfo{FileName=System.Reflection.Assembly.GetExecutingAssembly().Location,Arguments="lifecycle "+BatchProcessor.Quote(root),UseShellExecute=false,CreateNoWindow=true})){bool exited=child.WaitForExit(8000);if(!exited){child.Kill();child.WaitForExit();}Check(exited&&child.ExitCode==0,"closing actual helper window exits helper process");}
  var app=new Application{ShutdownMode=ShutdownMode.OnExplicitShutdown};var initial=FfmpegProcesses();var ui=new PreprocessWindow(root);ui.View.Show();ui.View.UpdateLayout();Check(!FfmpegProcesses().Except(initial).Any(),"opening preprocessing UI does not start FFmpeg");
  var visual=(FrameworkElement)ui.View.Content;int width=(int)visual.ActualWidth,height=(int)visual.ActualHeight;var drawing=new DrawingVisual();using(var context=drawing.RenderOpen()){context.DrawRectangle(ui.View.Background,null,new Rect(0,0,width,height));context.DrawRectangle(new VisualBrush(visual),null,new Rect(0,0,width,height));}var render=new RenderTargetBitmap(width,height,96,96,PixelFormats.Pbgra32);render.Render(drawing);var png=new PngBitmapEncoder();png.Frames.Add(BitmapFrame.Create(render));using(var file=File.Create(Path.Combine(root,"preview-preprocess.png")))png.Save(file);ui.View.Close();app.Shutdown();
 }
 static void RunFfmpeg(string executable,string arguments){using(var process=Process.Start(new ProcessStartInfo{FileName=executable,Arguments=arguments,UseShellExecute=false,CreateNoWindow=true,RedirectStandardError=true})){string error=process.StandardError.ReadToEnd();process.WaitForExit();if(process.ExitCode!=0)throw new Exception(error);}}
 static void RetimedApng(string source,string target){byte[] bytes=File.ReadAllBytes(source);int frame=0;for(int p=8;p+12<=bytes.Length;){int length=(bytes[p]<<24)|(bytes[p+1]<<16)|(bytes[p+2]<<8)|bytes[p+3];if(System.Text.Encoding.ASCII.GetString(bytes,p+4,4)=="fcTL"){int timing=p+8+20;bytes[timing]=0;bytes[timing+1]=(byte)(12*(++frame));bytes[timing+2]=0;bytes[timing+3]=100;uint crc=0xffffffff;for(int i=p+4;i<p+8+length;i++){crc^=bytes[i];for(int b=0;b<8;b++)crc=(crc&1)!=0?(crc>>1)^0xedb88320:crc>>1;}crc^=0xffffffff;int end=p+8+length;bytes[end]=(byte)(crc>>24);bytes[end+1]=(byte)(crc>>16);bytes[end+2]=(byte)(crc>>8);bytes[end+3]=(byte)crc;}p+=length+12;}File.WriteAllBytes(target,bytes);}
}
